  function applyDesign(){const d=config.design||emptyConfig().design;const root=document.documentElement;root.style.setProperty('--accent',safeColor(d.accent));root.style.setProperty('--page-bg',safeColor(d.background));root.style.setProperty('--title-ink',safeColor(d.title));root.style.setProperty('--text-ink',safeColor(d.text||'#233235'));root.style.setProperty('--surface-bg',safeColor(d.surface||'#ffffff'));root.style.setProperty('--muted-ink',safeColor(d.muted||d.title||'#667573'));root.style.setProperty('--border-ink',safeColor(d.border||'#e3ded8'));root.style.setProperty('--button-bg',safeColor(d.button||d.title||'#3a8588'));root.style.setProperty('--button-ink',safeColor(d.buttonText||'#ffffff'));root.style.setProperty('--shadow-ink',safeColor(d.shadow||d.title||'#5a7977'));root.style.setProperty('--toast-bg',safeColor(d.toast||d.button||d.title||'#3a8588'));root.style.setProperty('--toast-ink',safeColor(d.toastText||d.buttonText||'#ffffff'));root.style.setProperty('--font-stack',fonts[d.font]||fonts.pretendard);}
  const db=firebase.initializeApp(firebaseConfig).database(),auth=firebase.auth();
  let config=emptyConfig(),orders={},production={},sales={},posts={},route='dashboard',adminTab='boards',date=today(),store='doan',selectedProduct='',selectedBoard='',productFilters={query:'',category:'',store:''},selectedProducts=new Set(),writingBoard='',calendarDay=today(),calendarMonth=today().slice(0,7),ready=false,loadError='',toastTimer;
