  function orderQty(day,sid,pid){return num(day?.[sid]?.[pid]);}
  function madeQty(day,pid){return num(day?.[pid]?.made);}
  function wasteQty(day,pid){return num(day?.[pid]?.waste);}
  function shippedQty(day,pid,sid){return num(day?.[pid]?.shipments?.[sid]);}
  function soldQty(day,sid,pid){return num(day?.[sid]?.rows?.[pid]);}
  function salesTotal(sid,pid){return Object.values(sales).reduce((sum,day)=>sum+soldQty(day,sid,pid),0);}
