  function validateConfig(next){if(next.products.length>3000||next.boards.length>100||next.categories.length>50||next.productCategories.length>100)throw Error('등록 가능 수를 초과했습니다.');if(new Set(next.products.map(p=>p.id)).size!==next.products.length||new Set(next.boards.map(b=>b.id)).size!==next.boards.length||new Set(next.productCategories.map(c=>c.id)).size!==next.productCategories.length)throw Error('중복된 ID가 있습니다.');return next;}
