  function onChange(e){if(e.target.closest('#design-form'))previewDesign();if(e.target.matches('input[data-select-product]')){if(e.target.checked)selectedProducts.add(e.target.value);else selectedProducts.delete(e.target.value);updateProductSelection();}if(e.target.id==='product-select-visible'){for(const input of document.querySelectorAll('[data-product-card]:not([hidden]) input[data-select-product]')){if(e.target.checked)selectedProducts.add(input.value);else selectedProducts.delete(input.value);}updateProductSelection();}if(e.target.id==='product-bulk-category')updateProductSelection();if(e.target.matches('[data-rich-size], [data-rich-color]')){const editor=document.querySelector('[data-rich-editor]');if(editor){editor.focus();if(richSelection){const selection=window.getSelection();selection.removeAllRanges();selection.addRange(richSelection);}document.execCommand(e.target.matches('[data-rich-size]')?'fontSize':'foreColor',false,e.target.value);}}if(e.target.id==='product-category-filter'){productFilters.category=e.target.value;filterProductCards();}if(e.target.id==='product-store-filter'){productFilters.store=e.target.value;filterProductCards();}if(e.target.id==='filter-date'){date=e.target.value||today();render();}if(e.target.id==='filter-store'){store=e.target.value;render();}if(e.target.id==='production-product'){selectedProduct=e.target.value;render();}if(e.target.id==='pos-file'){posRows=null;$('pos-preview').innerHTML=e.target.files?.[0]?'<button id="pos-parse" class="primary">파일 읽기·열 확인</button>':'';}}
  let posRows=null,posHeaders=[],posSource='',posFile=null;
  function csv(text){const rows=[],line=[];let field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){line.push(field);field='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;line.push(field);field='';if(line.some(x=>x.trim()))rows.push(line.splice(0));else line.length=0;}else field+=ch;}line.push(field);if(line.some(x=>x.trim()))rows.push(line);return rows;}
  async function zipEntry(bytes,name){const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(view.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('올바른 .xlsx 파일이 아닙니다.');let offset=view.getUint32(end+16,true);for(let i=0;i<view.getUint16(end+10,true);i++){if(view.getUint32(offset,true)!==0x02014b50)throw Error('엑셀 압축 구조를 읽지 못했습니다.');const method=view.getUint16(offset+10,true),size=view.getUint32(offset+20,true),nl=view.getUint16(offset+28,true),extra=view.getUint16(offset+30,true),comment=view.getUint16(offset+32,true),local=view.getUint32(offset+42,true),entry=new TextDecoder().decode(bytes.slice(offset+46,offset+46+nl));if(entry===name){if(size>15e6)throw Error('시트 용량이 너무 큽니다.');const begin=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true),part=bytes.slice(begin,begin+size);if(method===0)return new TextDecoder().decode(part);if(method===8)return await new Response(new Blob([part]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text();throw Error('지원하지 않는 압축 방식입니다.');}offset+=46+nl+extra+comment;}return null;}
  async function xlsx(file){const bytes=new Uint8Array(await file.arrayBuffer()),sheet=await zipEntry(bytes,'xl/worksheets/sheet1.xml');if(!sheet)throw Error('첫 번째 시트를 찾지 못했습니다.');const strings=await zipEntry(bytes,'xl/sharedStrings.xml'),shared=[];if(strings){const xml=new DOMParser().parseFromString(strings,'application/xml');for(const item of xml.getElementsByTagName('si'))shared.push([...item.getElementsByTagName('t')].map(x=>x.textContent||'').join(''));}const doc=new DOMParser().parseFromString(sheet,'application/xml');if(doc.querySelector('parsererror'))throw Error('엑셀 시트를 읽지 못했습니다.');return [...doc.getElementsByTagName('row')].map(row=>{const cells=[];for(const cell of row.getElementsByTagName('c')){const letters=(cell.getAttribute('r')||'A').match(/^[A-Z]+/)[0];let n=0;for(const ch of letters)n=n*26+ch.charCodeAt(0)-64;n--;const type=cell.getAttribute('t'),value=cell.getElementsByTagName('v')[0]?.textContent||'';cells[n]=type==='s'?(shared[Number(value)]||''):type==='inlineStr'?[...cell.getElementsByTagName('t')].map(x=>x.textContent||'').join(''):value;}return cells.map(x=>x??'');});}
  async function parsePosFile(){const file=$('pos-file')?.files?.[0]||posFile;if(!file||file.size>5e6)throw Error('5MB 이하의 파일을 선택하세요.');posFile=file;posSource=file.name;const rows=file.name.toLowerCase().endsWith('.xlsx')?await xlsx(file):file.name.toLowerCase().endsWith('.csv')?csv(new TextDecoder('utf-8').decode(await file.arrayBuffer()).replace(/^\uFEFF/,'')):null;if(!rows||rows.length<2)throw Error('제목 행과 판매 자료가 있는 .xlsx 또는 .csv를 선택하세요.');posHeaders=rows[0].map((x,i)=>String(x||`열 ${i+1}`));posRows=rows.slice(1).filter(row=>row.some(x=>String(x).trim())).slice(0,10000);const field=(name,hints)=>{const match=posHeaders.findIndex(h=>hints.some(x=>h.replace(/\s/g,'').toLowerCase().includes(x)));return `<label class="field">${name}<select data-pos-column="${name}">${posHeaders.map((h,i)=>`<option value="${i}" ${i===match?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`;};$('pos-preview').innerHTML=`<h3>열 연결 · ${posRows.length}행</h3><div class="grid four">${field('date',['날짜','일자','date'])}${field('store',['지점','점포','매장','store'])}${field('product',['제품','상품','메뉴','product'])}${field('quantity',['수량','판매량','quantity','qty'])}</div><div class="table-scroll gap-top"><table class="data-table"><thead><tr>${posHeaders.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${posRows.slice(0,5).map(row=>`<tr>${posHeaders.map((_,i)=>`<td>${esc(row[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><button id="pos-save" class="primary gap-top">자료 검사·업로드</button><p class="muted gap-top">첫 시트의 첫 행을 열 제목으로 사용합니다. 날짜·지점·제품·판매수량이 명확히 구분된 POS 전체 일별 자료를 사용하세요.</p>`;notify('엑셀 열을 확인하세요.');}
  function parseDate(value){let s=String(value??'').trim();if(/^\d+(\.\d+)?$/.test(s)){const d=new Date(Date.UTC(1899,11,30)+Number(s)*86400000);s=d.toISOString().slice(0,10);}else{s=s.replace(/[.\/년월]/g,'-').replace(/일/g,'').replace(/-+$/,'').trim();const m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)s=`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;}return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))?s:null;}
  function matchStore(value){const s=String(value||'').replace(/\s/g,'').toLowerCase();return STORES.find(([key,name])=>s===key||s===name.replace('점','')||s===name)?.[0]||null;}
  async function savePos(){if(!root()||!posRows)throw Error('hare01 로그인과 POS 파일을 확인하세요.');const columns=Object.fromEntries([...document.querySelectorAll('[data-pos-column]')].map(el=>[el.dataset.posColumn,Number(el.value)]));if(new Set(Object.values(columns)).size!==4)throw Error('서로 다른 열을 선택하세요.');const batches={},unmatched=new Set(),bad=[];for(let i=0;i<posRows.length;i++){const row=posRows[i],day=parseDate(row[columns.date]),sid=matchStore(row[columns.store]),label=String(row[columns.product]||'').trim(),qty=Number(String(row[columns.quantity]||'').replace(/,/g,'')),p=config.products.find(p=>p.name===label||config.aliases?.[label]===p.id);if(!day||!sid||!label||!Number.isSafeInteger(qty)||qty<0){bad.push(i+2);continue;}if(!p){unmatched.add(label);continue;}const key=day+'|'+sid;batches[key]??={};batches[key][p.id]=(batches[key][p.id]||0)+qty;}if(bad.length)throw Error(`날짜·지점·수량을 확인하세요. 오류 행: ${bad.slice(0,8).join(', ')}${bad.length>8?' 외':''}`);if(unmatched.size){const names=[...unmatched];const host=$('pos-preview');host.insertAdjacentHTML('beforeend',`<div class="notice warn gap-top">연결되지 않은 POS 제품 ${names.length}개: ${names.map(esc).join(', ')}. 아래에서 제품을 연결한 뒤 다시 업로드하세요.</div><div class="stack gap-top" id="pos-mappings">${names.map((name,i)=>`<label class="field">${esc(name)}<select data-alias="${esc(name)}"><option value="">제품 선택</option>${optionRows(config.products.map(p=>[p.id,p.name]),'')}</select></label>`).join('')}<button type="button" class="primary" id="alias-save">제품명 연결 저장</button></div>`);throw Error('미연결 제품을 먼저 확인하세요.');}if(!Object.keys(batches).length)throw Error('업로드할 판매 자료가 없습니다.');const details=Object.entries(batches).map(([key,row])=>`${key.replace('|',' · ')}: ${Object.values(row).reduce((a,v)=>a+v,0)}개`).join('\n');if(!confirm(`${Object.keys(batches).length}개 날짜·지점의 POS 판매 수량을 교체합니다.\n\n${details.slice(0,1000)}\n\n계속할까요?`))return;const updates={};for(const [key,rows] of Object.entries(batches)){const [day,sid]=key.split('|');updates[`sales/${day}/${sid}`]={rows,filename:posSource,importedAt:firebase.database.ServerValue.TIMESTAMP};}await db.ref(ROOT).update(updates);notify('POS 판매 자료를 반영했습니다.');posRows=null;posFile=null;$('pos-file').value='';$('pos-preview').innerHTML='';}
  async function saveAliases(){if(!root())return;const rows=[...document.querySelectorAll('[data-alias]')],aliases=Object.fromEntries(rows.map(el=>[el.dataset.alias,el.value]));if(Object.values(aliases).some(x=>!x))throw Error('모든 POS 제품에 통합 제품을 지정하세요.');await saveConfig(c=>{c.aliases={...c.aliases,...aliases};});await parsePosFile();notify('제품명을 연결했습니다. 업로드를 다시 누르세요.');}
  let richSelection=null;document.addEventListener('selectionchange',()=>{const editor=document.querySelector('[data-rich-editor]'),selection=window.getSelection();if(editor&&selection?.rangeCount&&editor.contains(selection.anchorNode))richSelection=selection.getRangeAt(0).cloneRange();});document.addEventListener('mousedown',e=>{if(e.target.closest('[data-rich-command]'))e.preventDefault();});
  $('login-form').addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();onSubmit(e);});document.addEventListener('submit',onSubmit);document.addEventListener('click',e=>{if(e.target.id==='alias-save'){saveAliases().catch(fail);return;}onClick(e);});document.addEventListener('change',onChange);document.addEventListener('input',e=>{if(e.target.closest('#design-form'))previewDesign();if(e.target.id==='product-search'){productFilters.query=e.target.value;filterProductCards();}});$('mobile-scrim').addEventListener('click',()=>{$('sidebar').classList.remove('open');$('mobile-scrim').hidden=true;});
  auth.onAuthStateChanged(()=>render());
  let received=0;const paths=['config','orders','production','sales','posts'];paths.forEach(path=>ref(path).on('value',snap=>{if(path==='config')config=withDefaultBoards(snap.val()?.version===2?snap.val():{});if(path==='orders')orders=snap.val()||{};if(path==='production')production=snap.val()||{};if(path==='sales')sales=snap.val()||{};if(path==='posts')posts=snap.val()||{};received++;if(received>=paths.length)ready=true;loadError='';render();},error=>{loadError=`Firebase 읽기 실패: ${error.message}. 새 포털 규칙을 확인하세요.`;ready=true;render();}));
